/**
 * The agent handle (plan §3.6, §7.2) against the shared vectors. `vectors/handle.json` was generated by an
 * implementation independent of this one (Python's hashlib and base64), and the plugin runs the same file (step
 * 7.15). Update it by regenerating it whole, never by editing a case to match this code.
 */
import { sha256 } from '@noble/hashes/sha2.js'
import { utf8ToBytes } from '@noble/hashes/utils.js'

import vectors from '../vectors/handle.json'
import { base32Lower, deriveHandle, handleSlug, handleWithSuffix } from '../handle'

describe('base32Lower is RFC 4648 base32, lower case, unpadded', () => {
  // RFC 4648 §10 test vectors, lower-cased with the padding removed.
  it.each([
    ['', ''],
    ['f', 'my'],
    ['fo', 'mzxq'],
    ['foo', 'mzxw6'],
    ['foob', 'mzxw6yq'],
    ['fooba', 'mzxw6ytb'],
    ['foobar', 'mzxw6ytboi'],
  ])('%j → %j', (input, output) => {
    expect(base32Lower(utf8ToBytes(input))).toBe(output)
  })
})

describe('every shared vector', () => {
  it('has the cases it runs', () => {
    expect(vectors.version).toBe(1)
    expect(vectors.cases).toHaveLength(10)
  })

  it.each(Object.entries(vectors.digests))('the digest of %s', (did, digest) => {
    expect(base32Lower(sha256(utf8ToBytes(did)))).toBe(digest)
  })

  it.each(vectors.cases.map((c) => [c.note, c] as const))('%s', (_, c) => {
    const result = deriveHandle(c.name, c.agentDid, c.taken)
    if ('handle' in c.expect) expect(result).toEqual({ ok: true, handle: c.expect.handle })
    else expect(result).toEqual({ ok: false, reason: c.expect.error })
  })
})

describe('the handle rules, each with its control', () => {
  const did = vectors.cases[0].agentDid

  it('is the same on every run for the same name and DID', () => {
    const runs = Array.from({ length: 5 }, () => deriveHandle('Notes helper', did, []))
    expect(new Set(runs.map((r) => JSON.stringify(r))).size).toBe(1)
  })

  it('two agents with one name get different handles', () => {
    const other = vectors.cases[1].agentDid
    expect(handleWithSuffix('Notes helper', did, 4)).not.toBe(handleWithSuffix('Notes helper', other, 4))
    // control: the slug part is the same, so the difference is the DID's suffix
    expect(handleSlug('Notes helper')).toBe('notes-helper')
  })

  it('a collision extends the suffix to six characters, and only then', () => {
    const four = handleWithSuffix('Notes helper', did, 4)
    expect(deriveHandle('Notes helper', did, [four])).toEqual({
      ok: true,
      handle: handleWithSuffix('Notes helper', did, 6),
    })
    // control: with an unrelated handle taken, the four-character handle is given
    expect(deriveHandle('Notes helper', did, ['other-abcd'])).toEqual({ ok: true, handle: four })
  })

  it('a collision at six characters too gives no handle', () => {
    const taken = [handleWithSuffix('Notes helper', did, 4), handleWithSuffix('Notes helper', did, 6)]
    expect(deriveHandle('Notes helper', did, taken)).toEqual({ ok: false, reason: 'handle-collision' })
  })

  it('the slug is at most 32 characters', () => {
    expect(handleSlug('x'.repeat(40))).toHaveLength(32)
    expect(handleSlug('x'.repeat(32))).toHaveLength(32)
  })
})
